Repository: Know Meet (React 19 web meeting app on LiveKit). Diff base: main; head: 11ecd347 (branch feat/web-conferencing-features). This is packet 1 of 7, feature area: chat + screen share + meeting-room core. Other areas are reviewed in separate packets; do not report a defect solely because code referenced from another area is not shown.

Acceptance criteria (phase goals). Participants can: share a screen and stop; send chat to everyone or privately to one participant; blur or replace their background; pick microphone, camera and speaker with levels and preview, before and during a meeting; get an "Enable audio" prompt when autoplay is blocked. Local history (PGlite idb://) and local recordings stay on the device. Recording needs consent. Secrets stay server-side and clients get short-lived tokens. No `any` in TypeScript. Tauri calls are guarded by isTauri(). Flat UI with no borders, outlines or strokes; WCAG 2.2 AA.

Review the following unified diff:

diff --git a/apps/web/src/presentation/meeting-room/domain/chat-audience.ts b/apps/web/src/presentation/meeting-room/domain/chat-audience.ts
new file mode 100644
index 00000000..2a166d21
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/domain/chat-audience.ts
@@ -0,0 +1,105 @@
+// TJ-ARCH-MOB-001 compliant
+// Who a chat message goes to, as the composer offers it, and how every message names
+// its audience (WC-2, WC-3). Pure functions over domain types; no framework imports.
+// The composer shows Everyone first and preselects it, but the audience it sends is
+// always built here from the visible choice, never left to a default downstream.
+import {
+  type ChatAudience,
+  type ChatMessage,
+  EVERYONE,
+  type ParticipantIdentity,
+  privateTo,
+  type RemoteParticipant,
+} from "@know-meet/domain";
+
+export const AUDIENCE_EVERYONE_LABEL = "Everyone";
+
+/** The composer's choice. A private choice keeps the name it was made with. */
+export type AudienceChoice =
+  | { readonly kind: "everyone" }
+  | { readonly kind: "private"; readonly to: ParticipantIdentity; readonly name: string };
+
+export const EVERYONE_CHOICE: AudienceChoice = { kind: "everyone" };
+
+const EVERYONE_VALUE = "everyone";
+const PRIVATE_PREFIX = "private:";
+
+export interface AudienceOption {
+  readonly value: string;
+  readonly label: string;
+  /** A recipient who left: still shown while chosen, so the choice is never silently replaced. */
+  readonly disabled: boolean;
+}
+
+export function choiceValue(choice: AudienceChoice): string {
+  return choice.kind === "everyone" ? EVERYONE_VALUE : `${PRIVATE_PREFIX}${choice.to}`;
+}
+
+/** True while a private recipient is still in the room (Everyone always is). */
+export function isChoicePresent(
+  choice: AudienceChoice,
+  remotes: readonly RemoteParticipant[],
+): boolean {
+  if (choice.kind === "everyone") return true;
+  return remotes.some((remote) => remote.identity === choice.to);
+}
+
+/** Everyone, then one option per remote participant by name, plus a chosen recipient who left. */
+export function audienceOptions(
+  choice: AudienceChoice,
+  remotes: readonly RemoteParticipant[],
+): readonly AudienceOption[] {
+  const options: AudienceOption[] = [
+    { value: EVERYONE_VALUE, label: AUDIENCE_EVERYONE_LABEL, disabled: false },
+  ];
+  for (const remote of remotes) {
+    options.push({
+      value: `${PRIVATE_PREFIX}${remote.identity}`,
+      label: remote.displayName,
+      disabled: false,
+    });
+  }
+  if (choice.kind === "private" && !isChoicePresent(choice, remotes)) {
+    options.push({ value: choiceValue(choice), label: `${choice.name} (left)`, disabled: true });
+  }
+  return options;
+}
+
+/** The choice a select value stands for, or null when it names nobody in the room. */
+export function choiceFromValue(
+  value: string,
+  remotes: readonly RemoteParticipant[],
+): AudienceChoice | null {
+  if (value === EVERYONE_VALUE) return EVERYONE_CHOICE;
+  if (!value.startsWith(PRIVATE_PREFIX)) return null;
+  const identity = value.slice(PRIVATE_PREFIX.length);
+  const remote = remotes.find((candidate) => candidate.identity === identity);
+  return remote === undefined
+    ? null
+    : { kind: "private", to: remote.identity, name: remote.displayName };
+}
+
+export function toChatAudience(choice: AudienceChoice): ChatAudience {
+  return choice.kind === "everyone" ? EVERYONE : privateTo(choice.to);
+}
+
+/**
+ * The audience line on a message: "Everyone", "Private to <name>" for one this client
+ * sent, "Private to you" for one it received. `recipientName` is the name the message
+ * was sent to (kept at send time, since the recipient may have left since).
+ */
+export function messageAudienceLabel(message: ChatMessage, recipientName: string | null): string {
+  if (message.audience.kind === "everyone") return AUDIENCE_EVERYONE_LABEL;
+  if (message.direction === "received") return "Private to you";
+  return `Private to ${recipientName ?? "someone who left"}`;
+}
+
+/** Name of the participant a sent private message went to, from the room as it is now. */
+export function currentRecipientName(
+  message: ChatMessage,
+  remotes: readonly RemoteParticipant[],
+): string | null {
+  const { audience } = message;
+  if (audience.kind !== "private") return null;
+  return remotes.find((remote) => remote.identity === audience.to)?.displayName ?? null;
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/chat/chat-composer.tsx b/apps/web/src/presentation/meeting-room/presentation/chat/chat-composer.tsx
new file mode 100644
index 00000000..cf8ed2b6
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/chat/chat-composer.tsx
@@ -0,0 +1,173 @@
+// TJ-ARCH-MOB-001 compliant
+// meet.html `#chat-form` with an explicit audience (WC-2, WC-3; wc04 spec case 1): a
+// native "Send to" select (Everyone, then each person in the room; Everyone is shown
+// and preselected), a line that says who will see the message, the message field and
+// Send. The audience sent is built from the visible choice every time. If a chosen
+// recipient leaves, the choice is kept and marked "(left)", Send is unavailable and the
+// line says why, so a private message can never fall back to everyone by itself.
+// Enter sends, Shift+Enter adds a line. On failure the text stays and the error is read
+// out; on success the field clears and keeps focus. Scenario contract: km-chat-audience,
+// km-chat-input, km-chat-send.
+import type { ChatSendError } from "@know-meet/application";
+import {
+  type ChatMessage,
+  MAX_CHAT_TEXT_LENGTH,
+  type RemoteParticipant,
+  type Result,
+} from "@know-meet/domain";
+import { Button } from "@know-meet/ui/components/button";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { NativeSelect, NativeSelectOption } from "@know-meet/ui/components/native-select";
+import { Textarea } from "@know-meet/ui/components/textarea";
+import { type RefObject, useId, useState } from "react";
+import {
+  type AudienceChoice,
+  audienceOptions,
+  choiceFromValue,
+  choiceValue,
+  EVERYONE_CHOICE,
+  isChoicePresent,
+} from "../../domain/chat-audience";
+import {
+  CHAT_COPY,
+  chatSendErrorText,
+  inputPrivate,
+  recipientLeft,
+  scopePrivate,
+} from "./chat-copy";
+
+interface ChatComposerProps {
+  readonly remotes: readonly RemoteParticipant[];
+  readonly inputRef: RefObject<HTMLTextAreaElement | null>;
+  readonly onSend: (
+    text: string,
+    choice: AudienceChoice,
+  ) => Promise<Result<ChatMessage, ChatSendError>>;
+}
+
+function ScopeLine({
+  id,
+  choice,
+  present,
+}: {
+  readonly id: string;
+  readonly choice: AudienceChoice;
+  readonly present: boolean;
+}) {
+  const text =
+    choice.kind === "everyone"
+      ? CHAT_COPY.scopeEveryone
+      : present
+        ? scopePrivate(choice.name)
+        : recipientLeft(choice.name);
+  return (
+    <p id={id} className="flex items-start gap-1.5 text-sm text-muted-foreground">
+      <KmIcon name={choice.kind === "everyone" ? "users" : "lock"} className="mt-0.5 size-4" />
+      <span>{text}</span>
+    </p>
+  );
+}
+
+export function ChatComposer({ remotes, inputRef, onSend }: ChatComposerProps) {
+  const ids = useId();
+  const [choice, setChoice] = useState<AudienceChoice>(EVERYONE_CHOICE);
+  const [text, setText] = useState("");
+  const [sending, setSending] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const present = isChoicePresent(choice, remotes);
+  const canSend = present && !sending && text.trim() !== "";
+  const scopeId = `${ids}-scope`;
+  const errorId = `${ids}-error`;
+
+  const submit = () => {
+    if (!canSend) return;
+    const sentChoice = choice;
+    setSending(true);
+    void onSend(text, sentChoice).then((result) => {
+      setSending(false);
+      if (result.ok) {
+        setText("");
+        setError(null);
+        inputRef.current?.focus({ preventScroll: true });
+        return;
+      }
+      const name = sentChoice.kind === "private" ? sentChoice.name : null;
+      setError(chatSendErrorText(result.error, text, name));
+    });
+  };
+
+  return (
+    <form
+      noValidate
+      aria-label={CHAT_COPY.title}
+      className="grid gap-s2"
+      onSubmit={(event) => {
+        event.preventDefault();
+        submit();
+      }}
+    >
+      <div className="grid gap-1.5">
+        <label htmlFor={`${ids}-audience`} className="text-sm font-semibold">
+          {CHAT_COPY.audienceLabel}
+        </label>
+        <NativeSelect
+          id={`${ids}-audience`}
+          data-testid="km-chat-audience"
+          value={choiceValue(choice)}
+          aria-describedby={scopeId}
+          onChange={(event) => {
+            const next = choiceFromValue(event.target.value, remotes);
+            if (next === null) return;
+            setChoice(next);
+            setError(null);
+          }}
+        >
+          {audienceOptions(choice, remotes).map((option) => (
+            <NativeSelectOption key={option.value} value={option.value} disabled={option.disabled}>
+              {option.label}
+            </NativeSelectOption>
+          ))}
+        </NativeSelect>
+        <ScopeLine id={scopeId} choice={choice} present={present} />
+      </div>
+      <label htmlFor={`${ids}-input`} className="text-sm font-semibold">
+        {choice.kind === "everyone" ? CHAT_COPY.inputEveryone : inputPrivate(choice.name)}
+      </label>
+      <div className="flex items-end gap-s2">
+        <Textarea
+          ref={inputRef}
+          id={`${ids}-input`}
+          data-testid="km-chat-input"
+          rows={1}
+          maxLength={MAX_CHAT_TEXT_LENGTH}
+          value={text}
+          aria-invalid={error === null ? undefined : true}
+          aria-describedby={error === null ? scopeId : `${scopeId} ${errorId}`}
+          className="max-h-40 min-h-size-control-h resize-none"
+          onChange={(event) => {
+            setText(event.target.value);
+            if (error !== null) setError(null);
+          }}
+          onKeyDown={(event) => {
+            if (event.key !== "Enter" || event.shiftKey || event.nativeEvent.isComposing) return;
+            event.preventDefault();
+            submit();
+          }}
+        />
+        <Button
+          type="submit"
+          size="icon"
+          aria-label={CHAT_COPY.send}
+          data-testid="km-chat-send"
+          disabled={!canSend}
+          aria-busy={sending ? true : undefined}
+        >
+          <KmIcon name="send" />
+        </Button>
+      </div>
+      <p id={errorId} role="alert" className="text-sm text-red-text empty:hidden">
+        {error}
+      </p>
+    </form>
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/chat/chat-control.tsx b/apps/web/src/presentation/meeting-room/presentation/chat/chat-control.tsx
new file mode 100644
index 00000000..1b995d3f
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/chat/chat-control.tsx
@@ -0,0 +1,31 @@
+// TJ-ARCH-MOB-001 compliant
+// meet.html `#ctl-chat`: a panel control. It opens the room sheet on the chat pane
+// (aria-controls the sheet, aria-expanded while that pane is open, active tone then)
+// and shows the count of messages received while the pane was closed, which is also in
+// its name. Scenario contract: km-room-chat-toggle.
+import { Ctl } from "../room-control";
+import { paneControlId, ROOM_SHEET_ID } from "../room-sheet/room-sheet";
+import { chatControlName } from "./chat-copy";
+
+interface ChatControlProps {
+  readonly open: boolean;
+  readonly unread: number;
+  readonly onToggle: () => void;
+}
+
+export function ChatControl({ open, unread, onToggle }: ChatControlProps) {
+  return (
+    <Ctl
+      id={paneControlId("chat")}
+      icon="chat"
+      label="Chat"
+      aria-label={chatControlName(unread)}
+      tone={open ? "active" : "rest"}
+      aria-controls={ROOM_SHEET_ID}
+      aria-expanded={open}
+      data-testid="km-room-chat-toggle"
+      badge={unread}
+      onClick={onToggle}
+    />
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/chat/chat-copy.ts b/apps/web/src/presentation/meeting-room/presentation/chat/chat-copy.ts
new file mode 100644
index 00000000..df36f245
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/chat/chat-copy.ts
@@ -0,0 +1,60 @@
+// TJ-ARCH-MOB-001 compliant
+// Copy for the room chat (WC-2, WC-3). Audiences are always said out loud: who sees a
+// message is stated before it is sent and on every message after. Errors give the
+// cause, then the fix. Domain and application carry codes only.
+import type { ChatSendError } from "@know-meet/application";
+import { MAX_CHAT_TEXT_LENGTH } from "@know-meet/domain";
+
+export const CHAT_COPY = {
+  title: "Meeting chat",
+  lede: "People who join later don’t see earlier messages.",
+  close: "Close chat",
+  logLabel: "Chat messages",
+  emptyHeading: "No messages yet",
+  emptyText: "Say hello, or share a link with the room.",
+  audienceLabel: "Send to",
+  scopeEveryone: "Everyone in the meeting sees this message.",
+  inputEveryone: "Message everyone",
+  send: "Send message",
+  you: "You",
+  empty: "Type a message first.",
+  tooLong: `Messages can be up to ${MAX_CHAT_TEXT_LENGTH.toLocaleString("en")} characters. Shorten it, then send it again.`,
+} as const;
+
+export function scopePrivate(name: string): string {
+  return `Only ${name} sees this message. It isn’t encrypted end to end.`;
+}
+
+export function inputPrivate(name: string): string {
+  return `Message ${name} privately`;
+}
+
+export function recipientLeft(name: string): string {
+  return `${name} left the meeting, so nothing was sent. Choose Everyone or someone still here.`;
+}
+
+/** The chat control's accessible name, with the unread count when there is one. */
+export function chatControlName(unread: number): string {
+  return unread === 0 ? "Chat" : `Chat, ${unread} unread`;
+}
+
+export function receivedAnnouncement(fromName: string, isPrivate: boolean): string {
+  return isPrivate ? `Private message from ${fromName}` : `New message from ${fromName}`;
+}
+
+export function chatSendErrorText(
+  error: ChatSendError,
+  text: string,
+  recipientName: string | null,
+): string {
+  switch (error.code) {
+    case "invalid-request":
+      return text.trim() === "" ? CHAT_COPY.empty : CHAT_COPY.tooLong;
+    case "recipient-not-present":
+      return recipientLeft(recipientName ?? "That person");
+    case "send-failed":
+      return "The message wasn’t sent. Check your connection, then send it again.";
+    case "connection-lost":
+      return "You’re not connected. Wait for the connection to come back, then send it again.";
+  }
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/chat/chat-message-item.tsx b/apps/web/src/presentation/meeting-room/presentation/chat/chat-message-item.tsx
new file mode 100644
index 00000000..51e121dc
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/chat/chat-message-item.tsx
@@ -0,0 +1,57 @@
+// TJ-ARCH-MOB-001 compliant
+// meet.html `.chat-msg` (WC-2, WC-3): the sender ("You" for your own), the audience
+// and the time on one line, the text below. Your messages sit at the end on an
+// `ember-soft` bubble; private messages from others on a `card` bubble; messages to
+// everyone from others are plain text. The audience is text on every message
+// ("Everyone", "Private to <name>", "Private to you"), with a lock glyph for private
+// ones, so it is never carried by colour or position alone. Scenario contract:
+// km-chat-message (data-audience), km-chat-message-text (exactly the text),
+// km-chat-message-audience.
+import type { ChatMessage } from "@know-meet/domain";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { cn } from "@know-meet/ui/lib/utils";
+import { messageAudienceLabel } from "../../domain/chat-audience";
+import { CHAT_COPY } from "./chat-copy";
+
+const timeFormat = new Intl.DateTimeFormat(undefined, { hour: "2-digit", minute: "2-digit" });
+
+interface ChatMessageItemProps {
+  readonly message: ChatMessage;
+  /** For a private message this client sent: the name it was sent to. */
+  readonly recipientName: string | null;
+}
+
+export function ChatMessageItem({ message, recipientName }: ChatMessageItemProps) {
+  const mine = message.direction === "sent";
+  const isPrivate = message.audience.kind === "private";
+  const sentAt = new Date(message.sentAt);
+  return (
+    <li
+      data-testid="km-chat-message"
+      data-audience={message.audience.kind}
+      className={cn("grid gap-0.5", mine && "justify-items-end")}
+    >
+      <span className="flex flex-wrap items-center gap-x-1.5 text-xs font-semibold text-muted-foreground">
+        <span>{mine ? CHAT_COPY.you : message.fromName}</span>
+        <span aria-hidden="true">·</span>
+        <span data-testid="km-chat-message-audience" className="inline-flex items-center gap-1">
+          {isPrivate ? <KmIcon name="lock" className="size-3.5" /> : null}
+          {messageAudienceLabel(message, recipientName)}
+        </span>
+        <time dateTime={sentAt.toISOString()} className="font-mono text-11 font-medium">
+          {timeFormat.format(sentAt)}
+        </time>
+      </span>
+      <span
+        data-testid="km-chat-message-text"
+        className={cn(
+          "block max-w-full text-foreground [overflow-wrap:anywhere] whitespace-pre-wrap",
+          mine && "rounded-base bg-ember-soft px-3 py-2.5",
+          !mine && isPrivate && "rounded-base bg-card px-3 py-2.5",
+        )}
+      >
+        {message.text}
+      </span>
+    </li>
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/chat/chat-panel.tsx b/apps/web/src/presentation/meeting-room/presentation/chat/chat-panel.tsx
new file mode 100644
index 00000000..58820e9a
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/chat/chat-panel.tsx
@@ -0,0 +1,101 @@
+// TJ-ARCH-MOB-001 compliant
+// meet.html chat pane (WC-2, WC-3): "Meeting chat" with a lede, the messages of this
+// session oldest first in a polite log, and the composer in the sheet's foot. Unlike the
+// prototype's conversation rail, every message (to everyone and private) is in one log,
+// each labelled with its audience, and the composer's "Send to" select picks the
+// audience (scenario contract). Opening the pane moves focus to the message field; new
+// messages keep the log scrolled to the end unless the reader has scrolled up.
+// Scenario contract: km-chat-panel.
+import type { ChatMessage, RemoteParticipant } from "@know-meet/domain";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { useEffect, useRef } from "react";
+import { currentRecipientName } from "../../domain/chat-audience";
+import { RoomSheetPane } from "../room-sheet/room-sheet-pane";
+import { ChatComposer } from "./chat-composer";
+import { CHAT_COPY } from "./chat-copy";
+import { ChatMessageItem } from "./chat-message-item";
+import type { ChatState } from "./use-chat";
+
+/** How close to the end (px) still counts as "reading the latest". */
+const STICK_TO_END_PX = 48;
+
+interface ChatPanelProps {
+  /** Chat is the sheet's current pane (open or closing). */
+  readonly shown: boolean;
+  /** The sheet is open on this pane: focus moves to the message field. */
+  readonly active: boolean;
+  readonly messages: readonly ChatMessage[];
+  readonly remotes: readonly RemoteParticipant[];
+  readonly chat: ChatState;
+  readonly onClose: () => void;
+}
+
+function useStickToEnd(count: number) {
+  const bodyRef = useRef<HTMLElement>(null);
+  const atEnd = useRef(true);
+  useEffect(() => {
+    const body = bodyRef.current;
+    if (body === null) return undefined;
+    const onScroll = () => {
+      atEnd.current = body.scrollHeight - body.scrollTop - body.clientHeight < STICK_TO_END_PX;
+    };
+    body.addEventListener("scroll", onScroll, { passive: true });
+    return () => body.removeEventListener("scroll", onScroll);
+  }, []);
+  useEffect(() => {
+    const body = bodyRef.current;
+    if (body !== null && atEnd.current && count > 0) body.scrollTop = body.scrollHeight;
+  }, [count]);
+  return bodyRef;
+}
+
+export function ChatPanel({ shown, active, messages, remotes, chat, onClose }: ChatPanelProps) {
+  const inputRef = useRef<HTMLTextAreaElement>(null);
+  const bodyRef = useStickToEnd(messages.length);
+  useEffect(() => {
+    if (active) inputRef.current?.focus({ preventScroll: true });
+  }, [active]);
+
+  return (
+    <RoomSheetPane
+      pane="chat"
+      testId="km-chat-panel"
+      shown={shown}
+      title={CHAT_COPY.title}
+      lede={
+        <>
+          <KmIcon name="users" className="size-4" />
+          <span>{CHAT_COPY.lede}</span>
+        </>
+      }
+      closeLabel={CHAT_COPY.close}
+      onClose={onClose}
+      bodyRef={bodyRef}
+      bodyLabel={CHAT_COPY.logLabel}
+      foot={<ChatComposer remotes={remotes} inputRef={inputRef} onSend={chat.send} />}
+    >
+      <div role="log" aria-label={CHAT_COPY.logLabel}>
+        {messages.length === 0 ? (
+          <div className="grid gap-1.5 py-s4 text-sm text-muted-foreground">
+            <strong className="font-display text-base text-foreground">
+              {CHAT_COPY.emptyHeading}
+            </strong>
+            <span>{CHAT_COPY.emptyText}</span>
+          </div>
+        ) : (
+          <ol className="grid gap-s3">
+            {messages.map((message) => (
+              <ChatMessageItem
+                key={message.id}
+                message={message}
+                recipientName={
+                  chat.recipientNames.get(message.id) ?? currentRecipientName(message, remotes)
+                }
+              />
+            ))}
+          </ol>
+        )}
+      </div>
+    </RoomSheetPane>
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/chat/use-chat.ts b/apps/web/src/presentation/meeting-room/presentation/chat/use-chat.ts
new file mode 100644
index 00000000..77846b3a
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/chat/use-chat.ts
@@ -0,0 +1,80 @@
+// TJ-ARCH-MOB-001 compliant
+// Room chat state that outlives the panel (WC-2, WC-3): the unread count on the Chat
+// control, the names private messages were sent to (kept at send time, because the
+// recipient may leave), and the send action. Messages themselves are the room
+// snapshot's append-only `chat`; nothing is copied out of it. While the panel is
+// closed, a received message is announced politely, since the hidden log cannot be.
+import type { ChatSendError, ConferencingUseCases } from "@know-meet/application";
+import type { ChatMessage, ChatMessageId, Result } from "@know-meet/domain";
+import { useCallback, useEffect, useRef, useState } from "react";
+import type { Announce } from "../../../guest-meeting/live-status";
+import { type AudienceChoice, toChatAudience } from "../../domain/chat-audience";
+import { receivedAnnouncement } from "./chat-copy";
+
+export interface ChatState {
+  readonly unread: number;
+  readonly recipientNames: ReadonlyMap<ChatMessageId, string>;
+  readonly send: (
+    text: string,
+    choice: AudienceChoice,
+  ) => Promise<Result<ChatMessage, ChatSendError>>;
+  /** Everything received so far counts as read (called when the panel opens or closes). */
+  readonly markSeen: () => void;
+}
+
+function receivedSince(chat: readonly ChatMessage[], seenUpTo: number): number {
+  // `chat` empties on the next connect; a shorter list means a new session.
+  const from = seenUpTo > chat.length ? 0 : seenUpTo;
+  let count = 0;
+  for (let index = from; index < chat.length; index += 1) {
+    if (chat[index]?.direction === "received") count += 1;
+  }
+  return count;
+}
+
+export function useChat(
+  conferencing: ConferencingUseCases,
+  chat: readonly ChatMessage[],
+  open: boolean,
+  announce: Announce,
+): ChatState {
+  const [seenUpTo, setSeenUpTo] = useState(0);
+  const [recipientNames, setRecipientNames] = useState<ReadonlyMap<ChatMessageId, string>>(
+    () => new Map(),
+  );
+  const announcedUpTo = useRef(chat.length);
+
+  useEffect(() => {
+    const from = announcedUpTo.current > chat.length ? 0 : announcedUpTo.current;
+    announcedUpTo.current = chat.length;
+    if (open) return;
+    for (let index = chat.length - 1; index >= from; index -= 1) {
+      const message = chat[index];
+      if (message?.direction === "received") {
+        announce(receivedAnnouncement(message.fromName, message.audience.kind === "private"));
+        return;
+      }
+    }
+  }, [chat, open, announce]);
+
+  const markSeen = useCallback(() => setSeenUpTo(chat.length), [chat.length]);
+
+  const send = useCallback(
+    async (text: string, choice: AudienceChoice) => {
+      const result = await conferencing.sendChat(text, toChatAudience(choice));
+      if (result.ok && choice.kind === "private") {
+        const { id } = result.value;
+        setRecipientNames((previous) => new Map(previous).set(id, choice.name));
+      }
+      return result;
+    },
+    [conferencing],
+  );
+
+  return {
+    unread: open ? 0 : receivedSince(chat, seenUpTo),
+    recipientNames,
+    send,
+    markSeen,
+  };
+}
