+  PlaybackBlocked,
+  RemoteParticipant,
+  Result,
+  ScreenShare,
+  SendFailed,
+  ShareNotStarted,
+  TrackKind,
+  Unsupported,
+} from "@know-meet/domain";
+import type { RoomCredentials } from "./ports.ts";
+
+/** The devices the browser reports and the ones in use. */
+export interface DeviceState {
+  /**
+   * Every microphone, camera and speaker, in browser order. Kept current in every
+   * connection state, including before `connect`, so the lobby can list devices (WC-5).
+   * Labels are empty until the site has permission for that kind.
+   */
+  readonly available: readonly MediaDevice[];
+  /** What each kind uses now; `null` means the system default. */
+  readonly active: ActiveDevices;
+}
+
+/**
+ * One immutable picture of the room. `getSnapshot` returns the same object until something
+ * changes, then a new one (the `useSyncExternalStore` contract).
+ */
+export interface RoomSnapshot {
+  readonly connection: ConnectionState;
+  /** Null until connected and again after disconnecting. */
+  readonly local: LocalParticipant | null;
+  /** Remote participants in the order they joined. */
+  readonly remotes: readonly RemoteParticipant[];
+  /** Screens being shared now: the local share first, then remote ones in join order. */
+  readonly screenShares: readonly ScreenShare[];
+  /**
+   * This session's chat, sent and received, oldest first. Append-only while connected, so a
+   * consumer can read only the entries past the length it last saw; empty again on the next
+   * `connect`. A sent message appears once the server accepted it.
+   */
+  readonly chat: readonly ChatMessage[];
+  readonly devices: DeviceState;
+  /** `blocked` while the browser refuses to play remote audio (WC-12). */
+  readonly audioPlayback: AudioPlayback;
+  /** The requested camera background and how far it has got (WC-4). */
+  readonly backgroundEffect: BackgroundEffectState;
+  /** What this browser can do. Fixed for the page's lifetime. */
+  readonly support: ConferencingSupport;
+}
+
+/** Which participant's which medium a media element should play. */
+export interface MediaTarget {
+  readonly identity: ParticipantIdentity;
+  readonly kind: MediaSource;
+}
+
+/** Applied while connecting, before any device is opened. */
+export interface ConnectOptions {
+  /**
+   * The lobby's choice (WC-5). A chosen device that is gone by then falls back to the system
+   * default; that is not an error.
+   */
+  readonly devices: DeviceChoice;
+}
+
+/** Forbidden: the media server rejected the token. ConnectionLost: it could not be reached. */
+export type ConnectError = Forbidden | ConnectionLost;
+
+/** PermissionDenied: the browser refused the device. ConnectionLost: not in the room. */
+export type MediaError = PermissionDenied | ConnectionLost;
+
+export type ScreenShareError = ShareNotStarted | Unsupported | ConnectionLost;
+
+/** SendFailed: connected, but the server did not take the message. */
+export type MessageSendError = SendFailed | ConnectionLost;
+
+export type DeviceError = DeviceNotFound | Unsupported | PermissionDenied | ConnectionLost;
+
+export type AudioStartError = PlaybackBlocked | ConnectionLost;
+
+export type BackgroundEffectError = Unsupported | EffectFailed | ConnectionLost;
+
+/**
+ * A realtime meeting room. The LiveKit adapter (`packages/realtime`) implements it; nothing
+ * here names a LiveKit type. See docs/adr/0001-realtime-room-port.md and
+ * docs/adr/0002-conferencing-ports-and-recording-consent.md.
+ *
+ * - After `connect` succeeds the local microphone and camera are off until enabled.
+ * - Every state change (connection, participants, mute, subscription, shares, chat,
+ *   devices, playback, effect) produces a new snapshot and then notifies every listener.
+ * - `attachMedia` binds an element to a target for as long as the binding lives: the
+ *   adapter attaches the track when it is subscribed (or published, for local video),
+ *   re-attaches when it is replaced, clears the element when it goes away, and the returned
+ *   function detaches. Attaching the local microphone or local screen-share audio does
+ *   nothing, so a participant never hears themselves. Audio elements play through the
+ *   active speaker.
+ * - Methods that act in the room return ConnectionLost when not connected (or
+ *   reconnecting, for sends), and never throw for an expected failure.
+ */
+export interface RealtimeRoom {
+  connect(
+    credentials: RoomCredentials,
+    options?: ConnectOptions,
+  ): Promise<Result<void, ConnectError>>;
+  disconnect(): Promise<void>;
+  setMediaEnabled(kind: TrackKind, enabled: boolean): Promise<Result<void, MediaError>>;
+  getSnapshot(): RoomSnapshot;
+  subscribe(listener: () => void): () => void;
+  attachMedia(target: MediaTarget, element: HTMLMediaElement): () => void;
+
+  /**
+   * Starts or stops sharing a screen, window or tab, chosen in the browser's own picker
+   * with no surface restriction. Sharing that the browser ends (its "Stop sharing" bar)
+   * leaves `screenShares` like a stop does. Unsupported where `support.screenShare` is.
+   */
+  setScreenShareEnabled(enabled: boolean): Promise<Result<void, ScreenShareError>>;
+
+  /**
+   * Sends one chat message to its audience and returns it as appended to `chat`. A private
+   * message reaches only `audience.to`; the receiver sees it as private to itself.
+   * Delivery is not acknowledged: success means the server accepted it.
+   */
+  sendChat(message: OutgoingChatMessage): Promise<Result<ChatMessage, MessageSendError>>;
+
+  /**
+   * Re-reads the device list into `devices.available`. Never opens a permission prompt;
+   * the adapter also refreshes by itself when the browser reports a device change.
+   */
+  refreshDevices(): Promise<void>;
+
+  /**
+   * Switches one kind to a listed device; the published track continues on it and the
+   * background effect, if any, carries over. `speaker` is Unsupported where
+   * `support.speakerSelection` is (no `setSinkId`), and is never attempted there.
+   */
+  selectDevice(kind: DeviceKind, id: DeviceId): Promise<Result<void, DeviceError>>;
+
+  /**
+   * Asks the browser to play remote audio. Call it only from a click or key handler, the
+   * "Enable audio" button; PlaybackBlocked means the browser still refused.
+   */
+  startAudio(): Promise<Result<void, AudioStartError>>;
+
+  /**
+   * Requests a camera background. The request holds for the session: while the camera is
+   * off it is `pending`, and it is reapplied when the camera track is replaced (device
+   * switch, camera toggled back on). `none` removes the processor. EffectFailed leaves the
+   * camera unprocessed and the state `failed`.
+   */
+  setBackgroundEffect(effect: BackgroundEffect): Promise<Result<void, BackgroundEffectError>>;
+
+  /**
+   * Sends one recording-consent message on the room's reserved consent topic, which is
+   * never the chat topic. Only the consent use cases call it.
+   */
+  sendConsentMessage(
+    message: ConsentMessage,
+    to: ChatAudience,
+  ): Promise<Result<void, MessageSendError>>;
+
+  /**
+   * Delivers every well-formed consent message received, with the sender the transport
+   * reported. Malformed messages are dropped. Returns the unsubscribe function.
+   */
+  onConsentMessage(listener: (envelope: ConsentEnvelope) => void): () => void;
+}
diff --git a/packages/domain/src/conferencing/chat-message.ts b/packages/domain/src/conferencing/chat-message.ts
new file mode 100644
index 00000000..d0457922
--- /dev/null
+++ b/packages/domain/src/conferencing/chat-message.ts
@@ -0,0 +1,73 @@
+import type { ParticipantIdentity } from "../meeting/participant.ts";
+
+/**
+ * Who a chat message is for. There is no default: every message names its audience, so a
+ * private message can never be sent to everyone by omission (safety check, WC-3).
+ *
+ * - `everyone`: every participant in the room at the time it is sent.
+ * - `private`: exactly one participant. The media server delivers it only to `to`; it is
+ *   not encrypted and the server can read it (contract risk acceptance).
+ */
+export type ChatAudience =
+  | { readonly kind: "everyone" }
+  | { readonly kind: "private"; readonly to: ParticipantIdentity };
+
+export const EVERYONE: ChatAudience = { kind: "everyone" };
+
+export function privateTo(to: ParticipantIdentity): ChatAudience {
+  return { kind: "private", to };
+}
+
+/** Opaque id of one message, unique within a room session. The adapter assigns it. */
+export type ChatMessageId = string & { readonly __brand: "ChatMessageId" };
+
+/** Ids are opaque transport values: this only marks a string as one. */
+export function toChatMessageId(value: string): ChatMessageId {
+  return value as ChatMessageId;
+}
+
+/** Message text after trimming: never empty, never longer than the limit. */
+export type ChatText = string & { readonly __brand: "ChatText" };
+
+/**
+ * Longest accepted message, counted in code points. A product limit, not a transport one:
+ * it keeps one message readable in the panel and bounds what a remote sender can push
+ * into this client's memory and local history.
+ */
+export const MAX_CHAT_TEXT_LENGTH = 2000;
+
+/** Trims the input. Returns null when the result is empty or longer than the limit. */
+export function parseChatText(value: unknown): ChatText | null {
+  if (typeof value !== "string") return null;
+  const text = value.trim();
+  const length = [...text].length;
+  if (length === 0 || length > MAX_CHAT_TEXT_LENGTH) return null;
+  return text as ChatText;
+}
+
+/**
+ * What a participant asks to send. `audience` is required: the type rejects a message
+ * built without one (conferencing-ports spec, case 2).
+ */
+export interface OutgoingChatMessage {
+  readonly text: ChatText;
+  readonly audience: ChatAudience;
+}
+
+/**
+ * One message in this client's chat for the current room session, sent or received.
+ *
+ * For a received private message `audience.to` is always this client's own identity: the
+ * media server delivered it here and nowhere else.
+ */
+export interface ChatMessage {
+  readonly id: ChatMessageId;
+  readonly direction: "sent" | "received";
+  readonly from: ParticipantIdentity;
+  /** The sender's display name when the message was sent or received. */
+  readonly fromName: string;
+  readonly audience: ChatAudience;
+  readonly text: ChatText;
+  /** Milliseconds since the Unix epoch, as the transport stamped it. */
+  readonly sentAt: number;
+}
diff --git a/packages/domain/src/conferencing/conferencing-error.ts b/packages/domain/src/conferencing/conferencing-error.ts
new file mode 100644
index 00000000..9114d5c3
--- /dev/null
+++ b/packages/domain/src/conferencing/conferencing-error.ts
@@ -0,0 +1,93 @@
+import type { DeviceKind } from "./devices.ts";
+import type { ConferencingSupport } from "./screen-share.ts";
+
+/** A feature this browser lacks. The control should not have been offered. */
+export interface Unsupported {
+  readonly code: "unsupported";
+  readonly feature: keyof ConferencingSupport;
+}
+
+/**
+ * No screen share began: the participant closed the browser's picker or the browser
+ * refused. Browsers report both the same way, so they are one case.
+ */
+export interface ShareNotStarted {
+  readonly code: "share-not-started";
+}
+
+/** The chosen device is not (or no longer) connected. */
+export interface DeviceNotFound {
+  readonly code: "device-not-found";
+  readonly kind: DeviceKind;
+}
+
+/** A private message named someone who is not in the room. Nothing was sent. */
+export interface RecipientNotPresent {
+  readonly code: "recipient-not-present";
+}
+
+/** The media server did not accept a message while the room was connected. */
+export interface SendFailed {
+  readonly code: "send-failed";
+}
+
+/** The browser still blocks audio playback; it needs a click on "Enable audio". */
+export interface PlaybackBlocked {
+  readonly code: "playback-blocked";
+}
+
+/** The background processor or its assets failed to load. The camera stays unprocessed. */
+export interface EffectFailed {
+  readonly code: "effect-failed";
+}
+
+/** A recording request or recording is already under way in this room. */
+export interface RecordingBusy {
+  readonly code: "recording-busy";
+}
+
+/** Why the local recorder could not start or had to stop. */
+export type RecorderFailureReason =
+  | "unsupported"
+  | "storage-unavailable"
+  | "quota-exceeded"
+  | "failed";
+
+/** The local recorder could not start, or stopped by itself. What it wrote is kept. */
+export interface RecorderFailed {
+  readonly code: "recorder-failed";
+  readonly reason: RecorderFailureReason;
+}
+
+/**
+ * Expected failures of the conferencing features. Kept apart from `MeetingError` so the
+ * meeting screens' exhaustive mapping stays as it is. Copy lives in presentation.
+ */
+export type ConferencingError =
+  | Unsupported
+  | ShareNotStarted
+  | DeviceNotFound
+  | RecipientNotPresent
+  | SendFailed
+  | PlaybackBlocked
+  | EffectFailed
+  | RecordingBusy
+  | RecorderFailed;
+
+export const conferencingErrors = {
+  unsupported: (feature: keyof ConferencingSupport): Unsupported => ({
+    code: "unsupported",
+    feature,
+  }),
+  shareNotStarted: (): ShareNotStarted => ({ code: "share-not-started" }),
+  deviceNotFound: (kind: DeviceKind): DeviceNotFound => ({ code: "device-not-found", kind }),
+  recipientNotPresent: (): RecipientNotPresent => ({ code: "recipient-not-present" }),
+  sendFailed: (): SendFailed => ({ code: "send-failed" }),
+  playbackBlocked: (): PlaybackBlocked => ({ code: "playback-blocked" }),
+  effectFailed: (): EffectFailed => ({ code: "effect-failed" }),
+  recordingBusy: (): RecordingBusy => ({ code: "recording-busy" }),
+  recorderFailed: (reason: RecorderFailureReason): RecorderFailed => ({
+    code: "recorder-failed",
+    reason,
+  }),
+} as const;
diff --git a/packages/domain/src/conferencing/screen-share.ts b/packages/domain/src/conferencing/screen-share.ts
new file mode 100644
index 00000000..ab12c90e
--- /dev/null
+++ b/packages/domain/src/conferencing/screen-share.ts
@@ -0,0 +1,54 @@
+import type { ParticipantIdentity, TrackKind } from "../meeting/participant.ts";
+
+/**
+ * Every medium a media element can play: a participant's microphone or camera, or the
+ * screen they share and the audio that comes with it.
+ */
+export type MediaSource = TrackKind | "screen-share" | "screen-share-audio";
+
+/** One screen being shared in the room, by this participant or another (WC-1). */
+export interface ScreenShare {
+  readonly identity: ParticipantIdentity;
+  /** True when this client is the one sharing. */
+  readonly isLocal: boolean;
+  /**
+   * True when this client receives the shared video, so it can be attached. Always true
+   * for the local share once it is published.
+   */
+  readonly subscribed: boolean;
+  /** True when the share carries tab or system audio. */
+  readonly hasAudio: boolean;
+}
+
+/** True when this client is sharing its screen. */
+export function isSharingLocally(shares: readonly ScreenShare[]): boolean {
+  return shares.some((share) => share.isLocal);
+}
+
+/**
+ * Whether this browser can do a feature at all. Controls for an unsupported feature are
+ * hidden or explained, never offered to fail (contract supported environments).
+ */
+export type Support = "supported" | "unsupported";
+
+/** What this browser can do beyond microphone and camera. */
+export interface ConferencingSupport {
+  /** `getDisplayMedia` exists. Phone browsers usually lack it. */
+  readonly screenShare: Support;
+  /** The background processor's requirements are met (WC-4). */
+  readonly backgroundEffects: Support;
+  /** `HTMLMediaElement.setSinkId` exists, so a speaker can be chosen (WC-6). */
+  readonly speakerSelection: Support;
+}
+
+export const NOTHING_SUPPORTED: ConferencingSupport = {
+  screenShare: "unsupported",
+  backgroundEffects: "unsupported",
+  speakerSelection: "unsupported",
+};
+
+/**
+ * Whether the browser lets this page play remote audio. Mirrors the media SDK's playback
+ * flag; `blocked` is when the "Enable audio" prompt shows (WC-12).
+ */
+export type AudioPlayback = "allowed" | "blocked";
diff --git a/packages/realtime/src/realtime-room/domain/chat-codec.ts b/packages/realtime/src/realtime-room/domain/chat-codec.ts
new file mode 100644
index 00000000..bcfc63ec
--- /dev/null
+++ b/packages/realtime/src/realtime-room/domain/chat-codec.ts
@@ -0,0 +1,94 @@
+import {
+  type ChatAudience,
+  type ChatMessage,
+  EVERYONE,
+  MAX_CHAT_TEXT_LENGTH,
+  type ParticipantIdentity,
+  parseChatText,
+  privateTo,
+  toChatMessageId,
+  toParticipantIdentity,
+} from "@know-meet/domain";
+
+/**
+ * Topic of chat text streams. `lk.chat` is the LiveKit docs convention, not an SDK constant;
+ * every Know Meet client (web and Flutter) uses this one value.
+ */
+export const CHAT_TOPIC = "lk.chat";
+
+/**
+ * Reserved topic of recording-consent messages. Never the chat topic, so a consent message is
+ * never shown as chat and a chat message never reaches the consent rules.
+ */
+export const CONSENT_TOPIC = "know-meet.recording-consent";
+
+/**
+ * Stream attribute that says who a message was addressed to. The receiver's stream info has
+ * no destination list, so the sender states it: `private` or `everyone`.
+ */
+export const AUDIENCE_ATTRIBUTE = "audience";
+const PRIVATE = "private";
+const PUBLIC = "everyone";
+
+/** Largest chat stream read: the text limit at four UTF-8 bytes per code point. */
+export const MAX_CHAT_STREAM_BYTES = MAX_CHAT_TEXT_LENGTH * 4;
+
+/** Largest consent stream read; the codec itself accepts at most 1024 characters. */
+export const MAX_CONSENT_STREAM_BYTES = 4096;
+
+/** The fields the SDK's `sendText` options need. A fresh object for every send. */
+export interface TextSendOptions {
+  topic: string;
+  destinationIdentities?: string[];
+  attributes: Record<string, string>;
+}
+
+/**
+ * Send options for one audience. Privacy boundary: a private message always carries exactly
+ * one destination identity, so the media server delivers it to that participant only; there
+ * is no branch that sends a private message without it.
+ */
+export function textSendOptions(topic: string, audience: ChatAudience): TextSendOptions {
+  if (audience.kind === "private") {
+    return {
+      topic,
+      destinationIdentities: [audience.to],
+      attributes: { [AUDIENCE_ATTRIBUTE]: PRIVATE },
+    };
+  }
+  return { topic, attributes: { [AUDIENCE_ATTRIBUTE]: PUBLIC } };
+}
+
+/** A received message marked private is private to this client; anything else is public. */
+export function receivedAudience(
+  attributes: Readonly<Record<string, string>> | undefined,
+  localIdentity: ParticipantIdentity,
+): ChatAudience {
+  return attributes?.[AUDIENCE_ATTRIBUTE] === PRIVATE ? privateTo(localIdentity) : EVERYONE;
+}
+
+/** One received text stream on the chat topic, as read from the SDK. */
+export interface ReceivedChatFacts {
+  readonly streamId: string;
+  readonly timestamp: number;
+  readonly attributes: Readonly<Record<string, string>> | undefined;
+  readonly from: string;
+  readonly fromName: string;
+  readonly text: string;
+  readonly localIdentity: ParticipantIdentity;
+}
+
+/** The chat entry for a received stream, or null when its text is empty or too long. */
+export function toReceivedChat(facts: ReceivedChatFacts): ChatMessage | null {
+  const text = parseChatText(facts.text);
+  if (text === null || facts.from === "") return null;
+  return {
+    id: toChatMessageId(facts.streamId),
+    direction: "received",
+    from: toParticipantIdentity(facts.from),
+    fromName: facts.fromName,
+    audience: receivedAudience(facts.attributes, facts.localIdentity),
+    text,
+    sentAt: facts.timestamp,
+  };
+}
diff --git a/packages/realtime/src/realtime-room/domain/screen-share-mapping.ts b/packages/realtime/src/realtime-room/domain/screen-share-mapping.ts
new file mode 100644
index 00000000..c603c7ab
--- /dev/null
+++ b/packages/realtime/src/realtime-room/domain/screen-share-mapping.ts
@@ -0,0 +1,55 @@
+import { type RemoteParticipant, type ScreenShare, toParticipantIdentity } from "@know-meet/domain";
+import { sameItems } from "./participant-mapping.ts";
+
+/** One screen-share publication as read from the SDK. */
+export interface ScreenShareFacts {
+  readonly identity: string;
+  readonly isLocal: boolean;
+  /** True when this client receives the video. The SDK reader sets it for the local share. */
+  readonly subscribed: boolean;
+  /** True when a screen-share audio track is published next to the video. */
+  readonly hasAudio: boolean;
+}
+
+export const NO_SCREEN_SHARES: readonly ScreenShare[] = [];
+
+/**
+ * The port's order: the local share first, then remote shares in the order their sharers
+ * appear in `remotes` (join order). Unchanged shares keep their references, and the previous
+ * array is returned when nothing changed.
+ */
+export function nextScreenShares(
+  previous: readonly ScreenShare[],
+  facts: readonly ScreenShareFacts[],
+  remotes: readonly RemoteParticipant[],
+): readonly ScreenShare[] {
+  const joinOrder = new Map<string, number>(
+    remotes.map((remote, index) => [remote.identity, index]),
+  );
+  const rank = (fact: ScreenShareFacts): number =>
+    fact.isLocal ? -1 : (joinOrder.get(fact.identity) ?? remotes.length);
+  const ordered = [...facts]
+    .filter((fact) => fact.isLocal || joinOrder.has(fact.identity))
+    .sort((a, b) => rank(a) - rank(b))
+    .map((fact) => reuse(previous, toScreenShare(fact)));
+  if (sameItems(previous, ordered)) return previous;
+  return ordered.length === 0 ? NO_SCREEN_SHARES : ordered;
+}
+
+function toScreenShare(facts: ScreenShareFacts): ScreenShare {
+  return {
+    identity: toParticipantIdentity(facts.identity),
+    isLocal: facts.isLocal,
+    subscribed: facts.isLocal || facts.subscribed,
+    hasAudio: facts.hasAudio,
+  };
+}
+
+function reuse(previous: readonly ScreenShare[], next: ScreenShare): ScreenShare {
+  const prior = previous.find(
+    (share) => share.identity === next.identity && share.isLocal === next.isLocal,
+  );
+  if (prior === undefined) return next;
+  const same = prior.subscribed === next.subscribed && prior.hasAudio === next.hasAudio;
+  return same ? prior : next;
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/screen-share.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/screen-share.ts
new file mode 100644
index 00000000..b83b9b4c
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/screen-share.ts
@@ -0,0 +1,57 @@
+import type { ScreenShareError } from "@know-meet/application";
+import {
+  type ConferencingSupport,
+  conferencingErrors,
+  err,
+  meetingErrors,
+  ok,
+  type Result,
+} from "@know-meet/domain";
+import type { ScreenShareCaptureOptions } from "livekit-client";
+import { errorName, mapScreenShareError } from "../../domain/error-mapping.ts";
+import type { SessionHost } from "./session-host.ts";
+
+/**
+ * The browser's own picker, with no surface restriction (port contract): screen, window or
+ * tab, the current tab included, switching allowed, and tab or system audio where the browser
+ * offers it (Chromium only; Firefox and WebKit return video alone). Resolution stays at the
+ * SDK default (1080p30, uncapped on Safari 17).
+ */
+const SHARE_OPTIONS: ScreenShareCaptureOptions = {
+  audio: true,
+  selfBrowserSurface: "include",
+  surfaceSwitching: "include",
+  systemAudio: "include",
+};
+
+export type SetScreenShareEnabled = (enabled: boolean) => Promise<Result<void, ScreenShareError>>;
+
+/**
+ * The port's `setScreenShareEnabled` (WC-1). Stopping unpublishes the video and its audio
+ * (a screen share cannot be muted). When the browser ends the share itself (its "Stop
+ * sharing" bar, or the shared window closing), the SDK unpublishes the ended tracks and the
+ * `LocalTrackUnpublished` refresh removes the share from the snapshot, exactly as a stop does.
+ */
+export function createSetScreenShareEnabled(
+  host: SessionHost,
+  support: ConferencingSupport,
+): SetScreenShareEnabled {
+  return async (enabled) => {
+    const active = host.joined();
+    if (active === null) return err(meetingErrors.connectionLost());
+    if (enabled && support.screenShare === "unsupported") {
+      return err(conferencingErrors.unsupported("screenShare"));
+    }
+    try {
+      await active.room.localParticipant.setScreenShareEnabled(enabled, SHARE_OPTIONS);
+    } catch (error) {
+      host.report({ type: "screen-share-failed", errorName: errorName(error) });
+      if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+      host.refresh();
+      return err(mapScreenShareError(error));
+    }
+    if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+    host.refresh();
+    return ok(undefined);
+  };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/text-streams.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/text-streams.ts
new file mode 100644
index 00000000..b2f25e56
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/text-streams.ts
@@ -0,0 +1,202 @@
+import type { MessageSendError } from "@know-meet/application";
+import {
+  type ChatAudience,
+  type ChatMessage,
+  type ConsentEnvelope,
+  type ConsentMessage,
+  conferencingErrors,
+  decodeConsentMessage,
+  encodeConsentMessage,
+  err,
+  meetingErrors,
+  type OutgoingChatMessage,
+  ok,
+  type Result,
+  toChatMessageId,
+  toParticipantIdentity,
+} from "@know-meet/domain";
+import type { Room, TextStreamReader } from "livekit-client";
+import type { MessageChannel } from "../../application/diagnostics.ts";
+import {
+  CHAT_TOPIC,
+  CONSENT_TOPIC,
+  MAX_CHAT_STREAM_BYTES,
+  MAX_CONSENT_STREAM_BYTES,
+  textSendOptions,
+  toReceivedChat,
+} from "../../domain/chat-codec.ts";
+import { errorName } from "../../domain/error-mapping.ts";
+import { displayNameFrom } from "../../domain/participant-mapping.ts";
+import type { Session, SessionHost } from "./session-host.ts";
+
+/** A sender that stalls mid-stream is given up on after this long. */
+const READ_TIMEOUT_MS = 10_000;
+
+/**
+ * Chat and recording consent over LiveKit text streams (WC-2, WC-3, WC-8, WC-9): `sendText`
+ * to send, `registerTextStreamHandler` to receive, one topic each. The deprecated
+ * `sendChatMessage` API is not used.
+ */
+export interface TextStreams {
+  /** This session's chat, oldest first; a new array on every append. */
+  chat(): readonly ChatMessage[];
+  /** Registers both topic handlers on a new SDK room, before it connects. */
+  attach(session: Session): void;
+  /** Empties the chat (a new connect, or leaving). */
+  reset(): void;
+  sendChat(message: OutgoingChatMessage): Promise<Result<ChatMessage, MessageSendError>>;
+  sendConsentMessage(
+    message: ConsentMessage,
+    to: ChatAudience,
+  ): Promise<Result<void, MessageSendError>>;
+  onConsentMessage(listener: (envelope: ConsentEnvelope) => void): () => void;
+}
+
+/** Consent envelopes kept while no listener exists; older ones are dropped first. */
+const MAX_HELD_CONSENT = 16;
+
+export function createTextStreams(host: SessionHost): TextStreams {
+  let chat: readonly ChatMessage[] = [];
+  const consentListeners = new Set<(envelope: ConsentEnvelope) => void>();
+  /**
+   * WC-9: a late joiner's consent session starts only after its join resolves, but the
+   * recorder sends "recording is running" as soon as the joiner appears. Envelopes that
+   * arrive while nobody listens are held (bounded, this session only) and handed to the
+   * first listener, so the prompt and indicator do not depend on which side was ready first.
+   */
+  let heldConsent: ConsentEnvelope[] = [];
+
+  const append = (message: ChatMessage): void => {
+    chat = [...chat, message];
+    host.refresh();
+  };
+
+  /** The whole text, or null when the stream is too large, stalls or breaks. */
+  const readText = async (
+    reader: TextStreamReader,
+    channel: MessageChannel,
+    maxBytes: number,
+  ): Promise<string | null> => {
+    const size = reader.info.size;
+    if (size !== undefined && size > maxBytes) {
+      host.report({ type: "message-dropped", channel, reason: "too-large" });
+      // Abort at once so the SDK stops buffering the rest of the stream.
+      void reader.readAll({ signal: AbortSignal.abort() }).catch(() => undefined);
+      return null;
+    }
+    try {
+      return await reader.readAll({ signal: AbortSignal.timeout(READ_TIMEOUT_MS) });
+    } catch {
+      host.report({ type: "message-dropped", channel, reason: "unreadable" });
+      return null;
+    }
+  };
+
+  const receiveChat = async (session: Session, reader: TextStreamReader, from: string) => {
+    const text = await readText(reader, "chat", MAX_CHAT_STREAM_BYTES);
+    if (text === null || !host.isCurrent(session)) return;
+    const { room } = session;
+    if (from === room.localParticipant.identity) return;
+    const message = toReceivedChat({
+      streamId: reader.info.id,
+      timestamp: reader.info.timestamp,
+      attributes: reader.info.attributes,
+      from,
+      fromName: displayNameFrom(from, room.remoteParticipants.get(from)?.name),
+      text,
+      localIdentity: toParticipantIdentity(room.localParticipant.identity),
+    });
+    if (message === null) {
+      host.report({ type: "message-dropped", channel: "chat", reason: "malformed" });
+      return;
+    }
+    append(message);
+  };
+
+  const receiveConsent = async (session: Session, reader: TextStreamReader, from: string) => {
+    const text = await readText(reader, "consent", MAX_CONSENT_STREAM_BYTES);
+    if (text === null || !host.isCurrent(session) || from === "") return;
+    const message = decodeConsentMessage(text);
+    if (message === null) {
+      host.report({ type: "message-dropped", channel: "consent", reason: "malformed" });
+      return;
+    }
+    // The sender is the identity the media server reported, never a payload field.
+    const envelope: ConsentEnvelope = { from: toParticipantIdentity(from), message };
+    if (consentListeners.size === 0) {
+      heldConsent = [...heldConsent, envelope].slice(-MAX_HELD_CONSENT);
+      return;
+    }
+    for (const listener of [...consentListeners]) listener(envelope);
+  };
+
+  /** Sends one text stream; a failure while still connected is the server's refusal. */
+  const send = async (
+    session: Session,
+    channel: MessageChannel,
+    text: string,
+    topic: string,
+    audience: ChatAudience,
+  ): Promise<Result<{ readonly id: string; readonly timestamp: number }, MessageSendError>> => {
+    try {
+      const options = textSendOptions(topic, audience);
+      const info = await session.room.localParticipant.sendText(text, options);
+      return ok({ id: info.id, timestamp: info.timestamp });
+    } catch (error) {
+      host.report({ type: "message-send-failed", channel, errorName: errorName(error) });
+      const stillLive = host.live() !== null && host.isCurrent(session);
+      return err(stillLive ? conferencingErrors.sendFailed() : meetingErrors.connectionLost());
+    }
+  };
+
+  return {
+    chat: () => chat,
+    attach: (session) => {
+      const room: Room = session.room;
+      room.registerTextStreamHandler(CHAT_TOPIC, (reader, sender) => {
+        void receiveChat(session, reader, sender.identity);
+      });
+      room.registerTextStreamHandler(CONSENT_TOPIC, (reader, sender) => {
+        void receiveConsent(session, reader, sender.identity);
+      });
+    },
+    reset: () => {
+      chat = [];
+      heldConsent = [];
+    },
+    sendChat: async (outgoing) => {
+      const session = host.live();
+      if (session === null) return err(meetingErrors.connectionLost());
+      const sent = await send(session, "chat", outgoing.text, CHAT_TOPIC, outgoing.audience);
+      if (!sent.ok) return sent;
+      if (!host.isCurrent(session)) return err(meetingErrors.connectionLost());
+      const local = session.room.localParticipant;
+      const message: ChatMessage = {
+        id: toChatMessageId(sent.value.id),
+        direction: "sent",
+        from: toParticipantIdentity(local.identity),
+        fromName: displayNameFrom(local.identity, local.name),
+        audience: outgoing.audience,
+        text: outgoing.text,
+        sentAt: sent.value.timestamp,
+      };
+      append(message);
+      return ok(message);
+    },
+    sendConsentMessage: async (message, to) => {
+      const session = host.live();
+      if (session === null) return err(meetingErrors.connectionLost());
+      const sent = await send(session, "consent", encodeConsentMessage(message), CONSENT_TOPIC, to);
+      return sent.ok ? ok(undefined) : sent;
+    },
+    onConsentMessage: (listener) => {
+      consentListeners.add(listener);
+      const held = heldConsent;
+      heldConsent = [];
+      for (const envelope of held) listener(envelope);
+      return () => {
+        consentListeners.delete(listener);
+      };
+    },
+  };
+}
